import React from "react";
import { motion } from "framer-motion";
import { FEATURES } from "./Content";
import { Palette, Ruler, Package, Truck, Award, Heart } from "lucide-react";

const iconMap = { Palette, Ruler, Package, Truck, Award, Heart };

export default function Features() {
  return (
    <section className="section" style={{ background: "#f8fafc" }}>
      <div className="container mx-auto">
        <motion.div className="mb-12 lg:mb-16 text-center" initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ duration: 0.6 }}>
          <div className="flex items-center justify-center gap-3 mb-6">
            <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
            <span className="section-overline">Why Choose Us</span>
            <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, #d4af37, transparent)" }} />
          </div>
          <h2 className="section-title">What makes us <span>different</span></h2>
        </motion.div>

        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
          {FEATURES.map((feature, i) => {
            const Icon = iconMap[Object.keys(iconMap)[i]] || Award;
            return (
              <motion.div key={feature.title} className="card text-center" initial={{ opacity: 0, y: 30 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ delay: i * 0.1, duration: 0.5 }} whileHover={{ y: -6 }}>
                <div className="w-16 h-16 mx-auto mb-5 rounded-2xl flex items-center justify-center" style={{ background: "rgba(212,175,55,0.15)" }}>
                  <Icon size={28} color="#d4af37" />
                </div>
                <h3 className="text-lg font-semibold mb-2" style={{ color: "#1a080a" }}>{feature.title}</h3>
                <p className="text-sm" style={{ color: "rgba(26,8,10,0.6)" }}>{feature.desc}</p>
              </motion.div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
